def diff(a,b,path=''):
 if isinstance(a,dict) and isinstance(b,dict):
  out=[]
  for k in sorted(a.keys()|b.keys()):
   p=path+'/'+k.replace('~','~0').replace('/','~1')
   if k not in a:out.append(dict(pointer=p,operation='add',old=None,new=b[k]))
   elif k not in b:out.append(dict(pointer=p,operation='remove',old=a[k],new=None))
   else:out+=diff(a[k],b[k],p)
  return out
 if isinstance(a,list) and isinstance(b,list):
  assert len(b)>=len(a)
  return sum((diff(x,b[i],path+'/'+str(i)) for i,x in enumerate(a)),[])+[dict(pointer=path+'/'+str(i),operation='add',old=None,new=b[i]) for i in range(len(a),len(b))]
 return [] if a==b else [dict(pointer=path,operation='replace',old=a,new=b)]
